type Greeter struct{ name string }

func (g *Greeter) Hello() string {
	if g == nil {
		return "hello, stranger"
	}
	return "hello, " + g.name
}

type Helloer interface{ Hello() string }

func main() {
	var g *Greeter
	var h Helloer = g
	fmt.Println(h == nil)
	fmt.Println(h.Hello())
}

type Logger interface{ Log(string) }

type fileLogger struct{ prefix string }

func (l *fileLogger) Log(msg string) { fmt.Println(l.prefix + msg) }

func newLogger(debug bool) Logger {
	var l *fileLogger
	if debug {
		l = &fileLogger{prefix: "[dbg] "}
	}
	return l
}

func main() {
	lg := newLogger(false)
	if lg != nil {
		lg.Log("start")
	}
	fmt.Println("done")
}
